//! Source-rendered GuíaSalud archive cards, scoped Search&Filter paging and distinct renditions.
use super::{common,static_list::blocks_for,Adapter,PlanRow};
use crate::guidelines::doc::{Block,BlockKind,DateObservation,FetchRecord,GuidelineDoc,Rights};
