pub struct EsGuiasalud;
fn field(root:ElementRef<'_>,name:&str)->Option<String>{
 let marker=root.select(&sel("strong")).find(|e|text_of(e)==name)?;let mut next=marker.next_sibling();let mut text=String::new();
 while let Some(node)=next{if let Some(e)=ElementRef::wrap(node){if matches!(e.value().name(),"br"|"p"|"div"|"strong"){break;}text.push_str(&text_of(&e));text.push(' ');}else if let Some(t)=node.value().as_text(){text.push_str(t);}next=node.next_sibling();}
 let text=text.split_whitespace().collect::<Vec<_>>().join(" ");(!text.is_empty()).then_some(text)
}
fn es_date(label:&str,raw:&str,url:&str)->DateObservation{
 let mut d=common::date(label,raw,url);let re=regex::Regex::new(r"(?i)^(\d{1,2})\s+([a-záéíóú]+),?\s+((?:19|20)\d{2})$").unwrap();let months=["enero","febrero","marzo","abril","mayo","junio","julio","agosto","septiembre","octubre","noviembre","diciembre"];
 let month_year=regex::Regex::new(r"(?i)^([a-záéíóú]+)\s+(?:de\s+)?((?:19|20)\d{2})$").unwrap();if let Some(c)=month_year.captures(&d.raw){if let Some(m)=months.iter().position(|v|*v==c[1].to_lowercase()){d.normalized=Some(format!("{}-{:02}",&c[2],m+1));}}
 if let Some(c)=re.captures(&d.raw){if let Some(m)=months.iter().position(|v|*v==c[2].to_lowercase()){if let Ok(day)=c[1].parse::<u8>(){if (1..=31).contains(&day){d.normalized=Some(format!("{}-{:02}-{day:02}",&c[3],m+1));}}}}d
}
fn asset_role(label:&str)->&'static str{match label.trim(){"Completa PDF"=>"full_guideline_pdf","Completa HTML"=>"full_guideline_html","Resumida PDF"=>"summary_pdf","Resumida HTML"=>"summary_html","Guía en capas"=>"layered_guideline","Mat. Metod. PDF"=>"methods","Exposición Pública"=>"public_review","Actualización tablas"=>"table_update","Revisión PDF"=>"review","Guía Rápida PDF"=>"quick_reference","Herramientas PDF"=>"tools","Versión en inglés PDF"=>"english_rendition","Versión para la ciudadanía"=>"citizen_version",_=>"other_source_asset"}}
fn scope(url:&Url)->Vec<(String,String)>{let mut p=url.query_pairs().filter(|(k,_)|k!="sf_paged").map(|(k,v)|(k.into_owned(),v.into_owned())).collect::<Vec<_>>();p.sort();p}
fn catalog(src:&SourceEntry,raw:&str,base:&Url)->Result<(Vec<PlanRow>,Option<String>,Value)>{
 let doc=Html::parse_document(raw);let form=doc.select(&sel("form[data-sf-form-id='1140'][data-results-url]")).next().context("GuíaSalud scoped archive form missing")?;
 let mut rows=vec![];let mut ids=HashSet::new();
 for a in doc.select(&sel(".titulo-guia h2 > a[href]")){
  let card=a.ancestors().filter_map(ElementRef::wrap).find(|e|e.value().id()==Some("main")).context("GuíaSalud source card wrapper missing")?;let title=text_of(&a);let id=field(card,"ID:").context("GuíaSalud card ID missing")?;
  if !regex::Regex::new(r"^gpc_\d+$").unwrap().is_match(&id){bail!("GuíaSalud unvalidated card identifier {id}");}if !ids.insert(id.clone()){bail!("GuíaSalud duplicate source card ID within result page: {id}");}
  let record=common::link(base,a.value().attr("href").unwrap()).context("GuíaSalud record URL invalid")?;let mut assets=vec![];let mut seen=HashSet::new();
  for link in card.select(&sel(".enlace > a[href]")){let label=link.select(&sel(".texto-descarga")).next().map(|e|text_of(&e)).context("GuíaSalud asset label missing")?;let Some(url)=common::link(base,link.value().attr("href").unwrap())else{continue};if seen.insert((url.clone(),label.clone())){assets.push(json!({"url":url,"label":label,"role":asset_role(&label)}));}}
  let selected=assets.iter().find(|a|a["role"]=="full_guideline_pdf").or_else(||assets.iter().find(|a|a["role"]=="full_guideline_html")).or_else(||assets.iter().find(|a|a["role"]=="summary_pdf"));
  let role=selected.map(|a|a["role"].as_str().unwrap()).unwrap_or("unresolved_full_guideline").to_string();let url=selected.and_then(|a|a["url"].as_str()).unwrap_or(&record).to_string();
  let edition=field(card,"Fecha de edición:").map(|v|es_date("Fecha de edición",&v,&record));let producers=card.select(&sel(".contenido-ficha a[href*='/entidad-elaboradora/']")).map(|e|json!({"name":text_of(&e),"url":e.value().attr("href").and_then(|h|common::link(base,h))})).collect::<Vec<_>>();
  let description=card.select(&sel(".descripcion")).next().map(|e|text_of(&e));let native_warning=card.select(&sel(".alert, .aviso, .aviso-vigencia")).map(|e|text_of(&e)).collect::<Vec<_>>();
  let work=id.clone();let mut row=PlanRow{source_id:src.id.clone(),doc_key:format!("{work}-unresolved"),url,title:Some(title),rendition:Some(if role.ends_with("pdf"){"pdf"}else{"html"}.into()),version:None,extra:json!({"work_key":work,"guide_id":id,"record_url":record,"source_role":role,"edition_date":edition,"producers":producers,"description":description,"native_warnings":native_warning,"assets":assets,"catalog_url":base.as_str(),"catalog_card_html":card.html()})};
  if role!="full_guideline_pdf"&&role!="summary_pdf"{row.extra["discovery_error"]=json!("Source full HTML/layered/other rendition requires its own validated clinical/question template; no summary or overview substituted for full body");}rows.push(row);
 }
 if rows.is_empty(){bail!("GuíaSalud archive has no valid source cards; empty/transient page is not a stopping rule");}
 let pager=doc.select(&sel(".wp-pagenavi")).collect::<Vec<_>>();if pager.len()>1{bail!("GuíaSalud ambiguous result pagers");}
 let mut next=None;let mut position=Value::Null;
 if let Some(pager)=pager.first(){let label=pager.select(&sel(".pages")).next().map(|e|text_of(&e)).context("GuíaSalud result pager label missing")?;let re=regex::Regex::new(r"Página\s+(\d+)\s+de\s+(\d+)").unwrap();let caps=re.captures(&label).context("GuíaSalud result pager state unrecognized")?;let current=caps[1].parse::<usize>()?;let last=caps[2].parse::<usize>()?;
  let expected=base.query_pairs().find(|(k,_)|k=="sf_paged").map(|(_,v)|v.parse::<usize>()).transpose()?.unwrap_or(1);if current!=expected||current==0||last<current{bail!("GuíaSalud returned pager inconsistent with requested page");}
  let links=pager.select(&sel("a.nextpostslink[href]")).collect::<Vec<_>>();if current<last&&links.len()!=1{bail!("GuíaSalud nonterminal result pager has no unique Next");}if current==last&&!links.is_empty(){bail!("GuíaSalud terminal pager unexpectedly has Next");}
  if let Some(a)=links.first(){let url=base.join(a.value().attr("href").unwrap())?;let number=url.query_pairs().find(|(k,_)|k=="sf_paged").and_then(|(_,v)|v.parse::<usize>().ok());if url.origin()!=base.origin()||url.path()!=base.path()||scope(&url)!=scope(base)||number!=Some(current+1){bail!("GuíaSalud Next changes query scope or skips a page");}next=Some(url.to_string());}position=json!({"source_label":label,"current":current,"last":last});
 }
 let checked=form.select(&sel("input[checked][name]")).map(|e|json!({"name":e.value().attr("name"),"value":e.value().attr("value")})).collect::<Vec<_>>();
 Ok((rows,next,json!({"source_url":base.as_str(),"query_scope":scope(base),"pager":position,"checked_form_state":checked,"scope":"actual Search&Filter archive result controls; title-tag and embedded widget page counts ignored"})))
}
fn record_metadata(raw:&str,base:&Url)->Result<Value>{
 let doc=Html::parse_document(raw);let roots=doc.select(&sel("article.mk-blog-single.gpc")).collect::<Vec<_>>();if roots.len()!=1{bail!("GuíaSalud expected one guideline record article, found {}",roots.len());}let root=roots[0];let mut dates=vec![];
 if let Some(time)=root.select(&sel("time.mk-post-date")).next(){if !text_of(&time).starts_with("Publicado"){bail!("GuíaSalud posting-date label changed");}let printed=time.select(&sel("a")).next().map(|e|text_of(&e)).context("GuíaSalud printed posting date missing")?;dates.push(es_date("Publicado (portal record)",&printed,base.as_str()));}
 for value in root.select(&sel(".mk-post-meta-structured-data [itemprop='dateModified']")){dates.push(common::date("dateModified (portal structured metadata)",&text_of(&value),base.as_str()));}
 let mut assets=vec![];for a in root.select(&sel(".enlace > a[href]")){let label=a.select(&sel(".texto-descarga")).next().map(|e|text_of(&e)).context("GuíaSalud record asset label missing")?;if let Some(url)=common::link(base,a.value().attr("href").unwrap()){assets.push(json!({"url":url,"label":label,"role":asset_role(&label)}));}}
 if assets.is_empty(){bail!("GuíaSalud guideline record emitted no labelled assets");}Ok(json!({"source_url":base.as_str(),"date_observations":dates,"assets":assets,"scope":"guideline catalog record and source attachments; posting/structured modification are not clinical recommendation review dates"}))
}
fn pdf_metadata(blocks:&[Block],url:&str)->Value{
 let edition=regex::Regex::new(r"Edición:\s*((?:19|20)\d{2})").unwrap();let doi=regex::Regex::new(r"(?i)DOI:\s*\[?(?:https?://doi\.org/)?(10\.\d{4,9}/[A-Za-z0-9_.-]+)").unwrap();let isbn=regex::Regex::new(r"ISBN:\s*([0-9-]+)").unwrap();let mut editions=vec![];let mut identifiers=vec![];let mut review=vec![];
 for b in blocks.iter().take(25){for c in edition.captures_iter(&b.text){editions.push(json!({"label":"Edición","raw":&c[1],"source_block_id":b.block_id,"source_url":url}));}for c in doi.captures_iter(&b.text){identifiers.push(json!({"type":"doi","value":&c[1],"source_block_id":b.block_id}));}for c in isbn.captures_iter(&b.text){identifiers.push(json!({"type":"isbn","value":&c[1],"source_block_id":b.block_id}));}if b.text.contains("La GPC ha sido revisada")||b.text.contains("Versión resumida"){review.push(json!({"text":b.text,"source_block_id":b.block_id}));}}
 let version=regex::Regex::new(r"(?i)Versión:\s*((?:enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)\s+(?:de\s+)?(?:19|20)\d{2})").unwrap();let mut printed_versions=vec![];let mut version_dates=vec![];for b in blocks.iter().take(80){for c in version.captures_iter(&b.text){printed_versions.push(json!({"label":"Versión (PDF)","raw":&c[1],"source_block_id":b.block_id,"source_url":url}));version_dates.push(es_date("Versión (PDF)",&c[1],url));}}
 json!({"editions":editions,"printed_versions":printed_versions,"printed_version_date_observations":version_dates,"identifiers":identifiers,"rendition_review_notices":review})
}
// Printed asset notices are independent of portal-wide licensing and editorial credits.
fn pdf_rights(blocks:&[Block],url:&str)->(Rights,Vec<Value>){
 let mut rights=common::unknown_rights();rights.evidence_urls.push(url.into());let mut notices=vec![];
 for(index,b)in blocks.iter().enumerate(){let lower=b.text.to_lowercase();let restricted=index<80&&(lower.contains("reservados todos los derechos")||lower.contains("todos los derechos reservados")||(lower.contains("esta publicación no puede ser reproducida")&&lower.contains("permiso por escrito")));if b.text.contains('©')||lower.contains("copyright")||lower.contains("creative commons")||lower.contains("licencia")||restricted{notices.push(json!({"source_block_id":b.block_id,"source_url":url,"text":b.text,"scope":"printed PDF notice; no portal-wide licence or holder from interleaved layout inferred"}));}if restricted{rights.status="restricted".into();rights.restrictions.push(b.text.clone());}}
 (rights,notices)
}
// Genuine physical18 shows these as section separators. The saved converter
// repeats them at the end of the preceding clinical cell; retain original table
// text, but scope derived statements before the following heading.
fn statement_cell(cell:&str)->(String,Option<String>){for heading in ["Diagnóstico diferencial de diabetes monogénica","Cribado de enfermedades autoinmunes asociadas"]{if cell.ends_with(&format!("{heading} {heading}")){let mut text=cell;while let Some(prefix)=text.strip_suffix(heading){text=prefix.trim_end();}return(text.to_string(),Some(heading.into()));}}(cell.to_string(),None)}
fn recommendation_rows(blocks:&mut Vec<Block>,url:&str)->Result<Vec<Value>>{
 let grade_context=blocks.iter().any(|b|b.text.contains("Implicaciones de la fuerza de recomendación en el sistema GRADE"));if !grade_context{return Ok(vec![]);}
 let bpc_context=blocks.iter().any(|b|b.text.contains("Recomendaciones de buena práctica clínica (BPC)"));let mut pending=vec![];let mut records=vec![];
 for table in blocks.iter().filter(|b|matches!(b.kind,BlockKind::Table{..})){
  let mut statements=vec![];let mut clinical_section=None::<String>;for (n,line) in table.text.lines().enumerate(){if !line.trim().starts_with('|'){continue;}let cells=line.trim().trim_matches('|').split('|').map(str::trim).collect::<Vec<_>>();if cells.len()!=2{continue;}let label=cells[0];if label.is_empty()&&cells[1].starts_with("Uso de anticuerpos frente a la célula beta"){clinical_section=Some("Uso de anticuerpos frente a la célula beta".into());continue;}if !matches!(label,"Fuerte a favor"|"Fuerte en contra"|"Débil a favor"|"Débil en contra"|"BPC")||cells[1].is_empty(){continue;}if label=="BPC"&&!bpc_context{continue;}
   let id=format!("{}-row-{}",table.block_id,n+1);let raw_text=cells[1].replace("\\|","|");let(text,following_heading)=statement_cell(&raw_text);let current_section=clinical_section.clone();let kind=BlockKind::Recommendation{label:(label=="BPC").then(||"BPC".into()),strength:(label!="BPC").then(||label.into()),certainty:None,population:None,grading_system:Some(if label=="BPC"{"Recomendaciones de buena práctica clínica (BPC)"}else{"GRADE"}.into()),qualifier:None};
   records.push(json!({"block_id":id,"source_table_block_id":table.block_id,"converted_table_line":n+1,"printed_label":label,"source_text":text,"original_source_cell":raw_text,"current_clinical_section":current_section,"following_section_heading_from_conversion_tail":following_heading,"source_url":url,"certainty":"not inferred from a separate evidence table","scope":"exact labelled converted source row; original table retained; graphical/merged-cell fidelity remains unverified"}));let mut path=table.heading_path.clone();if let Some(section)=current_section{if path.last()!=Some(&section){path.push(section);}}statements.push(Block{block_id:id,kind,text,heading_path:path,page:None});if let Some(section)=following_heading{clinical_section=Some(section);}
  }if !statements.is_empty(){pending.push((table.block_id.clone(),statements));}
 }for (id,statements) in pending{let paths=statements.iter().map(|b|(b.block_id.clone(),b.heading_path.clone())).collect::<HashMap<_,_>>();common::insert_table_recommendations(blocks,&id,statements)?;for block in blocks.iter_mut(){if let Some(path)=paths.get(&block.block_id){block.heading_path=path.clone();}}}Ok(records)
}
#[async_trait::async_trait]
impl Adapter for EsGuiasalud{
 async fn discover(&self,src:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{
  if limit==Some(0){return Ok(vec![]);}let mut url=src.catalog_url.clone().context("GuíaSalud catalog missing")?;let mut pages=HashSet::new();let mut works=HashMap::<String,usize>::new();let mut out:Vec<PlanRow>=vec![];
  loop{if !pages.insert(url.clone()){bail!("GuíaSalud pager cycle");}if pages.len()>100{bail!("GuíaSalud result graph exceeds100pages");}let page=f.get_ok(&url).await?;let base=Url::parse(&page.record.final_url)?;let(rows,next,state)=catalog(src,&page.text(),&base)?;
   for mut row in rows{let member=format!("{}:{}:{}",row.extra["guide_id"].as_str().unwrap(),row.extra["source_role"].as_str().unwrap(),row.url);if let Some(index)=works.get(&member){out[*index].extra["additional_catalog_cards"].as_array_mut().unwrap().push(row.extra);continue;}works.insert(member,out.len());row.extra["additional_catalog_cards"]=json!([]);row.extra["catalog_state"]=state.clone();row.extra["catalog_fetch"]=json!(page.record);
    if row.extra["discovery_error"].is_null(){let result=async{let pdf=f.get_ok(&row.url).await?;if !pdf.is_pdf(){bail!("GuíaSalud labelled PDF returned an HTML wrapper, not PDF bytes");}Ok::<_,anyhow::Error>(pdf.record)}.await;match result{Ok(record)=>{row.doc_key=format!("{}-{}-{}",row.extra["work_key"].as_str().unwrap(),row.extra["source_role"].as_str().unwrap(),&record.sha256[..12]);row.extra["pdf_sha256"]=json!(record.sha256);},Err(error)=>row.extra["discovery_error"]=json!(format!("{error:#}"))}}
    out.push(row);if limit.is_some_and(|n|out.len()>=n){return Ok(out);}
   }match next{Some(next)=>url=next,None=>break,}
  }Ok(out)
 }
 async fn extract(&self,src:&SourceEntry,f:&Fetcher,row:&PlanRow)->Result<GuidelineDoc>{
  if let Some(error)=row.extra["discovery_error"].as_str(){bail!("GuíaSalud discovery: {error}");}let source_record=f.get_ok(row.extra["record_url"].as_str().context("GuíaSalud record URL missing")?).await?;let record=record_metadata(&source_record.text(),&Url::parse(&source_record.record.final_url)?)?;if !record["assets"].as_array().unwrap().iter().any(|a|a["url"]==row.url&&a["role"]==row.extra["source_role"]){bail!("GuíaSalud source record changed its selected labelled rendition; re-plan");}let pdf=f.get_ok(&row.url).await?;if !pdf.is_pdf(){bail!("GuíaSalud primary rendition is not actual PDF bytes");}if row.extra["pdf_sha256"].as_str().is_some_and(|s|s!=pdf.record.sha256){bail!("GuíaSalud rendition changed after planning; re-plan");}
  let(mut blocks,mut warnings,_)=blocks_for(&pdf,None,30).await?;if blocks.is_empty(){bail!("GuíaSalud PDF has no extracted body");}for b in &mut blocks{b.page=None;}let metadata=pdf_metadata(&blocks,&row.url);let recommendations=recommendation_rows(&mut blocks,&row.url)?;
  let mut dates:Vec<DateObservation>=serde_json::from_value(record["date_observations"].clone())?;if !row.extra["edition_date"].is_null(){dates.push(serde_json::from_value::<DateObservation>(row.extra["edition_date"].clone())?);}let editions=metadata["editions"].as_array().unwrap().iter().filter_map(|v|v["raw"].as_str()).collect::<HashSet<_>>();let versions=metadata["printed_versions"].as_array().unwrap().iter().filter_map(|v|v["raw"].as_str()).collect::<HashSet<_>>();let version=if versions.len()==1{versions.iter().next().map(|v|v.to_string())}else if versions.is_empty()&&editions.len()==1{editions.iter().next().map(|v|v.to_string())}else{None};dates.extend(serde_json::from_value::<Vec<DateObservation>>(metadata["printed_version_date_observations"].clone())?);
  let(rights,notices)=pdf_rights(&blocks,&row.url);
  let mut fetches=vec![];if let Ok(record)=serde_json::from_value::<FetchRecord>(row.extra["catalog_fetch"].clone()){fetches.push(record);}fetches.push(source_record.record);fetches.push(pdf.record.clone());
  warnings.push("Catalog edition date, PDF edition, posting/review notices and source query scope are distinct. Presence in All or historical/current-filter results is not synthesized into clinical currentness. Upload path dates are not publication dates; no unlinked2012 predecessor is emitted as a typed relation.".into());
  warnings.push("PDF conversion can repeat text fragments and interleave cells/columns; original converted tables retained. Exact labelled GRADE/BPC rows are separately associated, without borrowing certainty from another table. Physical pages, diagrams, merged cells and complete visual semantics remain unverified. Full HTML/layered/question/evidence assets require their own source-specific mapping; overview/summary is not substituted for a declared full body. Portal-wide CC terms are not assigned to externally produced PDFs without individual scope proof.".into());
  let doi=metadata["identifiers"].as_array().unwrap().iter().find(|v|v["type"]=="doi").and_then(|v|v["value"].as_str()).map(String::from);let issuers=row.extra["producers"].as_array().into_iter().flatten().filter_map(|p|p["name"].as_str().map(String::from)).collect();
  Ok(GuidelineDoc{source_id:src.id.clone(),doc_key:row.doc_key.clone(),work_key:row.extra["work_key"].as_str().map(String::from),title:row.title.clone().context("GuíaSalud source title missing")?,url:row.url.clone(),item_type:Some(if row.extra["source_role"]=="summary_pdf"{"guideline_summary"}else{"clinical_practice_guideline"}.into()),status:"unknown".into(),version,doi,issuers,date_observations:dates,rights,blocks,attachments:row.extra["assets"].as_array().cloned().unwrap_or_default(),search_metadata:json!({"source_catalog":row.extra,"source_record":record,"source_pdf_metadata":metadata,"source_rights_notices":notices,"printed_recommendation_rows":recommendations,"coverage":{"converted_blocks_available":true,"physical_pages":"unmapped","complete_visual_semantics":false}}),fetches,warnings,..Default::default()})
 }
}
