  let temp=tempfile::tempdir().unwrap();let f=Fetcher::new(temp.path(),true,1,2<<20,"").unwrap();f.seed_cache_for_tests(&row.url,PDF,"application/pdf");f.seed_cache_for_tests("https://portal.guiasalud.es/gpc/diabetes-mellitus-tipo-1/",RECORD.as_bytes(),"text/html");let d=EsGuiasalud.extract(&source,&f,&row).await.unwrap();assert_eq!(d.doc_key,row.doc_key);assert_eq!(d.item_type.as_deref(),Some("clinical_practice_guideline"));assert!(d.date_observations.iter().any(|v|v.label=="Fecha de edición"&&v.normalized.as_deref()==Some("2026-01-26")));assert!(d.date_observations.iter().any(|v|v.label=="Publicado (portal record)"&&v.normalized.as_deref()==Some("2026-01-28")));assert!(d.date_observations.iter().any(|v|v.label=="dateModified (portal structured metadata)"&&v.normalized.as_deref()==Some("2026-03-02")));assert!(d.published.is_none()&&d.updated.is_none()&&d.version.is_none()&&d.country.is_none());
