 #[test]
 fn genuine_graded_rows_preserve_age_antibody_and_treatment_conditions(){
  let gold:Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/es_guiasalud/diabetes-full-blocks.json"))).unwrap();let mut blocks:Vec<Block>=serde_json::from_value(gold["blocks"].clone()).unwrap();assert_eq!(blocks.iter().filter(|b|matches!(b.kind,BlockKind::Table{..})).count(),16);let before=blocks.iter().map(|b|(b.block_id.clone(),b.text.clone())).collect::<Vec<_>>();let records=recommendation_rows(&mut blocks,gold["source_pdf_url"].as_str().unwrap()).unwrap();assert!(!records.is_empty());
  let antibody=blocks.iter().find(|b|matches!(&b.kind,BlockKind::Recommendation{label:Some(label),strength:None,certainty:None,..} if label=="BPC")&&b.text.starts_with("En caso de negatividad de los anticuerpos")).unwrap();assert!(antibody.text.contains("mantenimiento de la sospecha de DM1")&&antibody.text.contains("preferiblemente antes del inicio del tratamiento con insulina")&&antibody.text.contains("(ZnT8)"));
  let genetic=blocks.iter().find(|b|matches!(&b.kind,BlockKind::Recommendation{strength:Some(grade),certainty:None,..} if grade=="Débil a favor")&&b.text.starts_with("En personas con diagnóstico de diabetes después de los 6 meses")).unwrap();assert!(genetic.text.contains("al menos dos generaciones")&&genetic.text.contains("al menos 5 años tras el diagnóstico"));assert_eq!(genetic.heading_path.last().map(String::as_str),Some("Diagnóstico diferencial de diabetes monogénica"));let sampling=blocks.iter().find(|b|matches!(b.kind,BlockKind::Recommendation{..})&&b.text.starts_with("Se sugiere extraer la muestra")).unwrap();assert!(sampling.text.contains("si los primeros fueran negativos."));assert!(!sampling.text.contains("Diagnóstico diferencial"));
  for(id,text)in before{assert_eq!(blocks.iter().find(|b|b.block_id==id).unwrap().text,text);}
  let metadata=pdf_metadata(&blocks,gold["source_pdf_url"].as_str().unwrap());assert!(metadata["editions"].as_array().unwrap().iter().any(|e|e["raw"]=="2026"));assert!(metadata["identifiers"].as_array().unwrap().iter().any(|e|e["type"]=="doi"&&e["value"]=="10.46995/gpc_659"));
 }
